// Meta webhook verification handshake.
// IMPORTANT: keep VERIFY_TOKEN identical to META_VERIFY_TOKEN in agent-api/.env
const VERIFY_TOKEN = 'change_me_verify_token';
const q = $input.first().json.query || {};
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VERIFY_TOKEN) {
  return [{ json: { challenge: q['hub.challenge'] || '' } }];
}
return [{ json: { challenge: 'forbidden' } }];

// Parse incoming payload. Handles BOTH the real Meta Cloud API format and the
// simple test/simulator format used by local curl + the test script.
const item = $input.first().json;
const body = item.body || item;

let message_text = '';
let user_phone = 'unknown';
let business_number = 'unknown';

// 1) Real Meta format: entry[0].changes[0].value.messages[0]
try {
  const value = body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
  const msg = value && value.messages && value.messages[0];
  if (msg) {
    message_text = (msg.text && msg.text.body) || '';
    user_phone = msg.from || 'unknown';
    business_number = (value.metadata && value.metadata.display_phone_number) || 'unknown';
  }
} catch (e) {}

// 2) Fallback: test/simulator format { message_text|message, from, to }
if (!message_text && (body.message_text || body.message)) {
  message_text = body.message_text || body.message || '';
  user_phone = body.from || 'unknown';
  business_number = body.to || 'unknown';
}

const has_message = message_text.trim().length > 0;

return [{ json: { message_text, user_phone, business_number, has_message, timestamp: new Date().toISOString() } }];

// Build dynamic system prompt: business prompt + server-rendered tool policy + after-hours.
const config = $('Load Config').first().json;
const businessId = $('Get Business ID').first().json.business_id;
const customerPhone = $('Parse Payload').first().json.user_phone;

let systemPrompt = config.system_prompt || '';
const enabledTools = config.enabled_tools || [];
const openingHours = config.opening_hours || null;
const timezone = config.timezone || 'Asia/Beirut';
const promptToolBlock = config.prompt_tool_block || '';

if (promptToolBlock) {
  systemPrompt += `\n\n${promptToolBlock}`;
}

// Tell the model the date and time in the business's timezone, so 'tomorrow' and 'Monday' resolve correctly
{
  const nowD = new Date();
  const ymd = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(nowD);
  const wd = nowD.toLocaleDateString('en-US', { timeZone: timezone, weekday: 'long' });
  const hm = nowD.toLocaleTimeString('en-GB', { timeZone: timezone, hour: '2-digit', minute: '2-digit' });
  systemPrompt += `\n\n[CURRENT DATE AND TIME] It is ${wd} ${ymd}, ${hm} (${timezone}). Work out relative dates yourself (today, tomorrow, Monday, next week) from this and pass them to tools as YYYY-MM-DD. Never ask the customer for the date of "tomorrow" or the day of the week.`;
}

let isAfterHours = false;
let hoursToday = null;
if (openingHours) {
  const now = new Date();
  const local = new Date(now.toLocaleString('en-US', { timeZone: timezone }));
  const dayNames = ['sun','mon','tue','wed','thu','fri','sat'];
  const today = dayNames[local.getDay()];
  hoursToday = openingHours[today];
  if (!hoursToday || hoursToday === 'closed') {
    isAfterHours = true;
  } else {
    const [open, close] = hoursToday.split('-');
    const [oh, om] = open.split(':').map(Number);
    const [ch, cm] = close.split(':').map(Number);
    const nowMins = local.getHours() * 60 + local.getMinutes();
    const openMins = oh * 60 + om;
    const closeMins = ch * 60 + cm;
    if (nowMins < openMins || nowMins >= closeMins) {
      isAfterHours = true;
    }
  }
}

if (isAfterHours) {
  systemPrompt += `\n\n[IMPORTANT] The business is currently closed (hours today: ${hoursToday || 'closed'}). Do NOT mention that the business is closed unless the customer asks for something only the staff can do (speaking to a person, a call back, a decision you cannot make, or anything your tools cannot do). In that case your reply MUST tell them the business is closed right now and when the team is next available, and that the team will follow up from then. ${config.closed_note || ''} Do not list the whole week's opening hours. Everything you can do with your tools (answering questions, orders, bookings, changes and cancellations) works normally, so just do it without mentioning the closed hours.`;
}

// Session memory: this session's messages (oldest first); past-session summaries only when the session just started
const sess = $input.first().json;
if (sess.is_new && (sess.past_summaries || []).length) {
  const hist = sess.past_summaries.map(s => `- ${String(s.started_at).slice(0, 10)}: ${s.summary}`).reverse();
  systemPrompt += `\n\n[CUSTOMER HISTORY - summaries of earlier conversations with this customer, oldest first; use for context, do not recite it]\n${hist.join('\n')}`;
}
if (sess.is_new && sess.profile) {
  const p = sess.profile; const bits = [];
  if (p.name) bits.push(`Name: ${p.name}`);
  if (p.language) bits.push(`Preferred language: ${p.language}`);
  if (p.preferences) bits.push(`Notes: ${p.preferences}`);
  if (bits.length) systemPrompt += `\n\n[CUSTOMER PROFILE - known facts about this customer]\n${bits.join('\n')}`;
}
const sessionMsgs = (sess.messages || []).filter(m => m && m.role && m.message);
if (sessionMsgs.length) {
  const lines = sessionMsgs.map(m => `${m.role === 'user' ? 'Customer' : 'Assistant'}: ${m.message}`);
  systemPrompt += `\n\n[CURRENT CONVERSATION - messages so far in this session; use for context, do not repeat answers already given]\n${lines.join('\n')}`;
}

// LANGUAGE RULE: reply in the customer's language; Arabic is always formal Modern Standard Arabic; Arabizi is understood but never written (see ARABIZI_POLICY)
const ARABIZI_POLICY = 'arabic'; // what to do when the customer writes Arabizi: 'arabic' (reply in Arabic script) | 'english' (reply in English) | 'ask' (ask which one they prefer)
let langRule = `\n\n[LANGUAGE - MANDATORY] Reply in the SAME language as the customer's LATEST message: English gets English, French gets French, Arabic script gets Arabic script. Never answer an English or French message in Arabic. Never repeat a word or phrase over and over. The customer may write Arabic in Latin letters (Arabizi, e.g. "kifak", "sa7be", "7a22o", "ma3ak"; numbers stand for Arabic letters: 2=hamza, 3=ain, 5=kh, 7=h, 8=gh, 9=q). Always UNDERSTAND Arabizi, but NEVER write Arabizi yourself.`;
if (ARABIZI_POLICY === 'english') {
  langRule += ` When the customer writes Arabizi, reply in English.`;
} else if (ARABIZI_POLICY === 'ask') {
  langRule += ` When the customer writes Arabizi and the conversation does not yet show which language they prefer, reply with ONLY this short question and nothing else: "هل تفضل المتابعة بالعربية أم بالإنجليزية؟ / Would you like to continue in Arabic or English?" Then answer their original request in the language they choose, and keep using it for the rest of the conversation without asking again.`;
} else {
  langRule += ` When the customer writes Arabizi, reply in Arabic script.`;
}
langRule += ` Whenever you write Arabic, use formal, polite and professional Modern Standard Arabic (الفصحى) with simple, clear wording. Do not use colloquial dialect or slang, even if the customer or earlier messages do. Examples of the tone: "أهلاً وسعداً بك، كيف يمكنني مساعدتك؟", "يسعدني خدمتك. يرجى تزويدي باسمك واليوم والساعة المناسبين لك", "تم حجز موعدك بنجاح", "شكراً لتواصلك معنا". In Arabic replies write numbers, dates, times, prices and order numbers with Western digits (0-9), and keep each sentence in one script: put product or service names written in Latin letters at the end of the sentence or on their own line instead of the middle of an Arabic sentence. Keep replies short. If the message is unclear, ask a short clarifying question instead of guessing.`;
systemPrompt += langRule;

// FORMATTING RULE: WhatsApp text only
systemPrompt += `\n\n[FORMATTING - MANDATORY] Plain text only. No markdown: no asterisks, no bold, no underscores, no headings, no backticks, no tables. For a list put each item on its own line starting with a dash and a space. Use a colon for label and value, and write prices the same way every time, for example "ERP system: 200$".`;

// CONFIRMATION RULE: changes to existing records need an explicit yes in a separate customer message
systemPrompt += `\n\n[AVAILABILITY WORDING - MANDATORY] When you tell the customer which appointment times are free, say it in one short sentence using the free_ranges from check_availability, for example "We have availability from 9:00 to 13:00 and from 15:00 to 17:30. What time suits you?". Never list the time slots one by one. If the customer asks you to stop messaging them (follow-ups, offers, 'don't contact me again'), you CAN do it: call the stop_followups tool (it is always allowed, even though it is not in the tool list above) and then confirm in one short sentence; never say you cannot, and do not argue or try to keep them. If the time the customer asks for is taken, suggest only the one or two closest free times, never a long list of windows. If the time asked for is outside opening hours, say that the business is open from X to Y that day (use the hours of that day) and ask for another time. If an order or appointment is not found on the customer's account, say you cannot find it and ask them to check the number; do not hand it to the team unless the customer asks for a person. When you list orders, write each one the same way: Order <number>: <quantity> x <item>, <total>$ total. [CONFIRMATION RULE - MANDATORY] Cancelling, editing or rescheduling an order or appointment is NEVER done on the customer's first message about it. First state exactly what you are about to change (which order/appointment, and the new time if rescheduling) and ask the customer to confirm. Only after the customer replies with a clear yes in a LATER message may you call cancel_order, edit_order, cancel_appointment or reschedule_appointment. If they have not confirmed yet, do not call those tools. To move an appointment to another time ALWAYS call reschedule_appointment; NEVER cancel it to rebook, because that leaves the customer without a booking. Short replies mean yes or no: yes = yes, yep, ok, okay, sure, eh, ey, e, aywa, aiwa, tamam, yalla, نعم, ايه, أكيد; no = no, la, laa, لا. Treat them as the customer's answer to your last question, keep replying in the language of the conversation so far, and never ask the customer to type a specific word to confirm.`;

systemPrompt += `\n\n[STRICT RULE] Call each tool AT MOST ONCE per user message. After a tool returns successfully, do NOT call it again - just reply confirming what was done.`;

systemPrompt += `\n\n[CONTEXT - DO NOT REVEAL]\nbusiness_id: ${businessId}\ncustomer_phone: ${customerPhone}`;

return [{
  json: {
    business_id: businessId,
    customer_phone: customerPhone,
    system_prompt: systemPrompt,
    enabled_tools: enabledTools,
    is_after_hours: isAfterHours,
    escalation_number: config.escalation_number || null,
    agent_started_at: Date.now(),
    workflow_version: 'wf-2026-10-27.1', // bump when the rules written in this step change
    model: 'gpt-6-luna', // keep equal to the model chosen in the OpenAI Chat Model node (used for the cost estimate)
    base_chars: systemPrompt.length + String($('Parse Payload').first().json.message_text || '').length
  }
}];

// One place that cleans the model's reply before it is logged, sent and returned
let t = String($('AI Agent').first().json.output || '').replace(/<think>[\s\S]*?<\/think>/g, '').split('</think>').pop().trim();
// plain text only: strip markdown the model sometimes adds anyway
t = t.replace(/\*\*(.+?)\*\*/gs, '$1').replace(/__(.+?)__/gs, '$1').replace(/`+/g, '')
     .replace(/^\s{0,3}#{1,6}\s+/gm, '').replace(/^\s*[*•]\s+/gm, '- ')
     .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '$1 $2');
// Arabic text with Latin words/numbers inside: isolate each Latin run so it keeps its own order (display only)
if (/[؀-ۿ]/.test(t)) {
  t = t.replace(/[A-Za-z0-9#$@][A-Za-z0-9#$@.,:'&%+\/\-]*(?: [A-Za-z0-9#$@][A-Za-z0-9#$@.,:'&%+\/\-]*)*/g, (m) => {
    const tail = (m.match(/[.,:'\-]+$/) || [''])[0];
    return '⁦' + m.slice(0, m.length - tail.length) + '⁩' + tail;
  });
}
return [{ json: { reply: t, agent_done_at: Date.now() } }];

// Collect everything about this turn for the trace log. Never fails the reply.
try {
  const bp = $('Build Prompt').first().json;
  const parse = $('Parse Payload').first().json;
  const agent = $('AI Agent').first().json;
  const clean = $('Clean Reply').first().json;
  const steps = (Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : []).map((s) => ({
    action: { tool: s.action && s.action.tool, toolInput: s.action && s.action.toolInput },
    observation: typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation),
  }));
  const debug = { agentKeys: Object.keys(agent).join(',') };
  let usage = null;
  const tu = agent.tokenUsage || agent.usage || (agent.response && agent.response.tokenUsage);
  if (tu && (tu.totalTokens || tu.total_tokens)) {
    usage = { prompt_tokens: tu.promptTokens || tu.prompt_tokens, completion_tokens: tu.completionTokens || tu.completion_tokens, total_tokens: tu.totalTokens || tu.total_tokens };
  }
  const now = Date.now();
  return [{ json: {
    business_id: bp.business_id, customer_phone: bp.customer_phone, session_id: $('Resolve Session').first().json.session.id,
    inbound_text: parse.message_text, reply: clean.reply, raw_reply: String(agent.output || ''), outcome: 'replied',
    steps, usage, model: bp.model, workflow_version: bp.workflow_version, base_chars: bp.base_chars,
    total_ms: now - new Date(parse.timestamp).getTime(), agent_ms: (clean.agent_done_at || now) - bp.agent_started_at,
    execution_id: $execution.id, trace_id: 'n8n-' + $execution.id, debug,
  } }];
} catch (e) {
  return [{ json: { business_id: $('Build Prompt').first().json.business_id, outcome: 'replied', execution_id: $execution.id,
    trace_id: 'n8n-' + $execution.id, debug: { buildError: String(e.message).slice(0, 200) } } }];
}
